insert into public.crop_catalog (id, position, name, space, data) values
  ('microgreens', 1, 'Microgreens', 'indoor', '{"id":"microgreens","name":"Microgreens","space":"indoor","scale":"m2","refQty":1.5,"minM2":1,"m2PerHead":null,"windows":[{"from":"01-01","to":"12-31"}],"firstIncomeDays":{"min":7,"max":15},"income":{"kind":"cycle","min":500,"max":1000,"cycleDays":{"min":7,"max":15}},"budget":{"min":200,"max":500,"refQty":1.5},"recurringMonthly":null,"hoursPerWeek":{"min":0,"max":7},"ps":null,"channels":["Ristoranti gourmet","Privati","Negozi","Mercatini","Agriturismi"],"priceNote":"€8–12 a vaschetta · 50–100 vaschette su 1–2 m² · ciclo veloce e continuo","salesCycle":"Semina in vassoi, 7–15 giorni di crescita, vendita viva in vaschetta. Il ciclo ricomincia subito: servono ordini regolari (ristoranti, clienti fissi), perché il prodotto non aspetta.","tasks":[{"title":"Semina vassoi microgreens","offsetDays":0,"everyDays":11},{"title":"Raccolta e consegna vaschette microgreens","offsetDays":11,"everyDays":11}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Coltura al chiuso: tutto l''anno (stima di Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["Lo schema dà €500–1.000 per ciclo: il tool lo converte in un ricavo al mese in base alla durata del ciclo (7–15 giorni).","Da chiarire con il SIAN se per la legge sono microgreens o ''germogli'' (Reg. UE 208/2013 e 210/2013)."]}'::jsonb),
  ('funghi', 2, 'Funghi (indoor)', 'indoor', '{"id":"funghi","name":"Funghi (indoor)","space":"indoor","scale":"m2","refQty":1,"minM2":1,"m2PerHead":null,"windows":[{"from":"01-01","to":"12-31"}],"firstIncomeDays":{"min":30,"max":30},"income":{"kind":"monthly","min":500,"max":1000},"budget":{"min":500,"max":1500,"refQty":5},"recurringMonthly":null,"hoursPerWeek":{"min":0,"max":7},"ps":{"value":38076,"per":100,"unit":"m2","source":"Tabella CREA usata dalla Regione Sardegna: funghi sotto copertura, per 100 m² di bancale, 7,2 cicli. Valore calabrese da chiedere al CAA."},"channels":["Ristoranti gourmet","Veg/vegani","Privati","Negozi bio"],"priceNote":"Fino a €30/kg · produzione ciclica mensile","salesCycle":"Un ciclo produttivo ogni 30 giorni: preparazione dei sacchi, incubazione, raccolta in più volate. Vendita fresca, a pochi giorni dalla raccolta.","tasks":[{"title":"Preparare il locale e i primi sacchi di substrato","offsetDays":0,"everyDays":null},{"title":"Controllo umidità e temperatura funghi","offsetDays":2,"everyDays":7},{"title":"Raccolta e vendita funghi, nuovi sacchi","offsetDays":30,"everyDays":30}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Coltura al chiuso: tutto l''anno (stima di Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["Lo schema dà €500–1.000/mese ''min. 1 mq'': il tool lo prende come ricavo per m². Va verificata la resa reale in kg/m².","Lo schema non dice a quanti m² corrisponde il budget (dice 1–5–10 m²): il tool assume 5 m²."]}'::jsonb),
  ('orto-eterno', 3, 'Orto eterno (no-dig)', 'outdoor', '{"id":"orto-eterno","name":"Orto eterno (no-dig)","space":"outdoor","scale":"m2","refQty":250,"minM2":250,"m2PerHead":null,"windows":[{"from":"01-01","to":"12-31"}],"firstIncomeDays":{"min":45,"max":90},"income":{"kind":"monthly","min":800,"max":800},"budget":{"min":400,"max":800,"refQty":250},"recurringMonthly":null,"hoursPerWeek":{"min":7,"max":7},"ps":null,"channels":["Ristoranti","Mercati","Privati","Vendita diretta","Bio"],"priceNote":"€20–35 a cassetta + trasformati · metodo no-dig","salesCycle":"Dopo l''avvio delle aiuole, raccolta continua tutto l''anno con semine di successione. Vendita a cassetta settimanale a clienti fissi e mercati.","tasks":[{"title":"Preparare le aiuole no-dig (cartone e compost)","offsetDays":0,"everyDays":null},{"title":"Prime semine e trapianti","offsetDays":7,"everyDays":null},{"title":"Semine di successione e pacciamatura","offsetDays":30,"everyDays":30},{"title":"Raccolta e preparazione cassette","offsetDays":45,"everyDays":7}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Schema: ''continuo tutto l''anno''","tasks":"Proposta di Claude, da verificare"},"notes":["Lo schema dà un solo valore (€800/mese su 250 m²): pessimista e ottimista coincidono, l''incertezza non è rappresentata.","Il primo ricavo ''dai primi mesi'' è stimato tra 45 e 90 giorni."]}'::jsonb),
  ('pollaio', 4, 'Pollaio da reddito', 'outdoor', '{"id":"pollaio","name":"Pollaio da reddito","space":"outdoor","scale":"capi","refQty":20,"minM2":null,"m2PerHead":3,"windows":[{"from":"01-01","to":"12-31"}],"firstIncomeDays":{"min":0,"max":30},"income":{"kind":"monthly","min":500,"max":700},"budget":{"min":1000,"max":1500,"refQty":20},"recurringMonthly":null,"hoursPerWeek":{"min":1,"max":3},"ps":null,"channels":["Ristoranti","Privati","Mercati","Vendita diretta","Didattica"],"priceNote":"Uova alimentari €0,80–1 · uova fertili €3","salesCycle":"Produzione subito se le galline sono già in deposizione. Raccolta giornaliera, vendita settimanale di uova fresche a clienti fissi e al mercato.","tasks":[{"title":"Raccolta, controllo e vendita uova della settimana","offsetDays":0,"everyDays":7},{"title":"Pulizia pollaio e cambio lettiera","offsetDays":14,"everyDays":30}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Schema: ''produzione immediata''","tasks":"Proposta di Claude, da verificare"},"notes":["Il ricavo scala sul numero di galline (schema: €500–700/mese con 20 galline), non sui m².","Lo schema indica 60–100 m² per 20 galline: il tool avvisa sotto i 3 m² per gallina.","Ore: ''4 ore/mese + raccolta giornaliera'', stimate in 1–3 ore a settimana.","Uova: esenzione dalla timbratura fino a 50 galline se si vende su mercato locale con nome e indirizzo (vedi Regolamenti)."]}'::jsonb),
  ('fiori-eduli-indoor', 5, 'Fiori eduli (indoor)', 'indoor', '{"id":"fiori-eduli-indoor","name":"Fiori eduli (indoor)","space":"indoor","scale":"m2","refQty":2,"minM2":2,"m2PerHead":null,"windows":[{"from":"01-01","to":"12-31"}],"firstIncomeDays":{"min":45,"max":75},"income":null,"budget":{"min":200,"max":500,"refQty":2},"recurringMonthly":null,"hoursPerWeek":{"min":7,"max":7},"ps":null,"channels":["Ristoranti","Pasticcerie","Privati","Organizzatori eventi"],"priceNote":"€0,30–0,50 a fiore · nicchia in crescita","salesCycle":"Semine scalari e raccolta continua. Vendita a fiore o a confezione, su ordinazione per ristoranti, pasticcerie ed eventi.","tasks":[{"title":"Semina scalare fiori eduli","offsetDays":0,"everyDays":14},{"title":"Raccolta e vendita fiori eduli","offsetDays":45,"everyDays":7}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Coltura al chiuso: tutto l''anno (stima di Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["Ricavo mancante: lo schema dice €500–1.000 ma non ogni quanto (al mese? all''anno?). Il tool non lo usa finché non lo verifichi.","Primo raccolto stimato tra 45 e 75 giorni."]}'::jsonb),
  ('fiori-eduli-outdoor', 6, 'Fiori eduli (outdoor)', 'outdoor', '{"id":"fiori-eduli-outdoor","name":"Fiori eduli (outdoor)","space":"outdoor","scale":"m2","refQty":20,"minM2":20,"m2PerHead":null,"windows":[{"from":"03-01","to":"05-31"}],"firstIncomeDays":{"min":45,"max":75},"income":null,"budget":{"min":200,"max":500,"refQty":20},"recurringMonthly":null,"hoursPerWeek":{"min":7,"max":7},"ps":null,"channels":["Ristoranti","Pasticcerie","Privati","Organizzatori eventi"],"priceNote":"€0,30–0,50 a fiore · nicchia in crescita","salesCycle":"Semina in primavera, fioritura e raccolta dalla tarda primavera all''autunno. Vendita a fiore o a confezione su ordinazione.","tasks":[{"title":"Semina e trapianto fiori eduli","offsetDays":0,"everyDays":null},{"title":"Raccolta e vendita fiori eduli","offsetDays":45,"everyDays":7}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Semina primaverile, marzo–maggio (stima di Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["Ricavo mancante: lo schema dice €500–1.000 ma non ogni quanto. Il tool non lo usa finché non lo verifichi.","La raccolta all''aperto è stagionale: i task settimanali vanno sospesi in inverno."]}'::jsonb),
  ('zafferano', 7, 'Zafferano', 'outdoor', '{"id":"zafferano","name":"Zafferano","space":"outdoor","scale":"m2","refQty":100,"minM2":100,"m2PerHead":null,"windows":[{"from":"08-01","to":"09-15"}],"firstIncomeDays":{"min":80,"max":110},"income":{"kind":"yearly","min":4800,"max":6000},"budget":{"min":3000,"max":4000,"refQty":100},"recurringMonthly":null,"hoursPerWeek":{"min":0,"max":7},"ps":null,"channels":["Ristoranti","Privati","Agriturismi","Cosmetica"],"priceNote":"€60–80/g · 10.000 bulbi in 100 m² · bulbi +30% ogni anno","salesCycle":"Messa a dimora dei bulbi in agosto, fioritura e raccolta in ottobre–novembre, essiccazione degli stimmi. Vendita in grammi nei mesi successivi: un solo incasso all''anno.","tasks":[{"title":"Preparare il terreno e mettere a dimora i bulbi","offsetDays":0,"everyDays":null},{"title":"Controllo infestanti zafferano","offsetDays":30,"everyDays":30},{"title":"Raccolta fiori e sfioritura (ogni mattina)","offsetDays":80,"everyDays":365},{"title":"Essiccazione, pesatura e vendita zafferano","offsetDays":100,"everyDays":365}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Schema: messa a dimora agosto (esteso al 15 settembre da Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["Ricavo dello schema: anno 1 ~€6.000 (80–100 g a €60/g) su 100 m².","La crescita dei bulbi (+30% l''anno) non è inclusa nei prospetti: richiede più spazio ogni anno."]}'::jsonb),
  ('lombricoltura', 8, 'Lombricoltura', 'outdoor', '{"id":"lombricoltura","name":"Lombricoltura","space":"outdoor","scale":"m2","refQty":15,"minM2":10,"m2PerHead":null,"windows":[{"from":"03-01","to":"06-30"},{"from":"09-01","to":"11-30"}],"firstIncomeDays":{"min":180,"max":365},"income":{"kind":"monthly","min":1250,"max":2500},"budget":{"min":500,"max":500,"refQty":15},"recurringMonthly":null,"hoursPerWeek":{"min":1,"max":2},"ps":null,"channels":["Aziende agricole","Privati","Settore pesca"],"priceNote":"Vermicompost €60/q · lombrichi €3 (12 pz) · humus liquido €15–20/l","salesCycle":"Avvio dei letti, 6–12 mesi prima del primo humus maturo. Poi vagliatura periodica e vendita di humus solido e liquido.","tasks":[{"title":"Allestire i letti e inserire i lombrichi","offsetDays":0,"everyDays":null},{"title":"Alimentare i lombrichi e controllare l''umidità","offsetDays":7,"everyDays":7},{"title":"Separare e vagliare l''humus","offsetDays":180,"everyDays":90}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Primavera e autunno, evitando caldo e freddo (stima di Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["ATTENZIONE: €15.000–30.000/anno su 10–20 m² non è plausibile. A €60/q vorrebbe dire 25–50 tonnellate di humus all''anno.","Il ricavo dello schema comprende la vendita di lombrichi, che hai escluso.","Per vendere humus serve l''iscrizione al Registro dei fabbricanti di fertilizzanti (D.Lgs. 75/2010).","Lo schema dice budget ''< €500'': il tool usa €500."]}'::jsonb),
  ('elicicoltura', 9, 'Elicicoltura (lumache)', 'outdoor', '{"id":"elicicoltura","name":"Elicicoltura (lumache)","space":"outdoor","scale":"m2","refQty":10000,"minM2":1000,"m2PerHead":null,"windows":[{"from":"03-01","to":"05-31"}],"firstIncomeDays":{"min":180,"max":210},"income":{"kind":"yearly","min":30000,"max":100000},"budget":{"min":5000,"max":5000,"refQty":1000},"recurringMonthly":null,"hoursPerWeek":null,"ps":{"value":45000,"per":10000,"unit":"m2","source":"Valore usato dalle Regioni Basilicata e Piemonte per l''elicicoltura (€45.000/ha). Valore calabrese da chiedere al CAA."},"channels":["Ristoranti","Privati","Cosmetica","Grossisti alimentari"],"priceNote":"Raccolta annuale · doppia fonte: carne + bava cosmetica","salesCycle":"Avvio in primavera con recinti e semine per l''alimentazione, raccolta in autunno. Vendita a grossisti e ristoranti, una volta l''anno.","tasks":[{"title":"Preparare recinti e semine per l''alimentazione","offsetDays":0,"everyDays":null},{"title":"Immissione dei riproduttori","offsetDays":14,"everyDays":365},{"title":"Controllo recinti, irrigazione e alimentazione","offsetDays":21,"everyDays":7},{"title":"Raccolta e vendita lumache","offsetDays":180,"everyDays":365}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Schema: avvio in primavera","tasks":"Proposta di Claude, da verificare"},"notes":["Lo schema dà €30.000–100.000 lordi per ettaro (netto €8.000–15.000/ha): il tool usa i lordi.","Ore di lavoro mancanti: lo schema dice solo ''stagionale''.","Lo schema dice budget ''€5.000+'' per il minimo di 1.000 m²: è un minimo."]}'::jsonb),
  ('olivo', 10, 'Olivo da specialista', 'outdoor', '{"id":"olivo","name":"Olivo da specialista","space":"outdoor","scale":"m2","refQty":10000,"minM2":10000,"m2PerHead":null,"windows":[{"from":"10-01","to":"03-31"}],"firstIncomeDays":{"min":1095,"max":1825},"income":null,"budget":{"min":5000,"max":5000,"refQty":10000},"recurringMonthly":null,"hoursPerWeek":null,"ps":null,"channels":["Privati","Ristoranti","Aziende alimentari","Fiere","E-commerce"],"priceNote":"Olio EVO €20–50/litro (contro €4–8 della grande distribuzione) · segmento premium/DOP","salesCycle":"Impianto dell''oliveto, 3–5 anni prima della produzione. Poi potatura e raccolta annuale, frangitura e vendita dell''olio imbottigliato.","tasks":[{"title":"Messa a dimora degli olivi","offsetDays":0,"everyDays":null},{"title":"Controllo e irrigazione delle giovani piante","offsetDays":30,"everyDays":30},{"title":"Potatura olivi","offsetDays":120,"everyDays":365}],"sources":{"data":"Schema operativo coltivazioni — Rendita Agricola","windows":"Impianto da ottobre a marzo (stima di Claude)","tasks":"Proposta di Claude, da verificare"},"notes":["Ricavo mancante: lo schema dà il prezzo al litro ma non la resa (litri per ettaro).","Lo schema indica 1–3 ettari: con 1.000 m² sei sotto il minimo.","Ore di lavoro mancanti: lo schema dice solo ''stagionale''."]}'::jsonb)
